// @lib controlid/lib/afd.mjs
// Leitor de AFD (Arquivo-Fonte de Dados) dos relógios de ponto REP — Portaria 671/2021 e Portaria 1510/2009 (legado).
// Funções puras, sem import: este arquivo é copiado para o nó Code "AFD · separar lotes" (convenção `// @lib` de docs/DIVISAO.md).
//
// Registros de marcação aproveitados (contrato §12.4):
//   Portaria 671, tipo 3 (REP-C, 50 colunas) e tipo 7 (REP-P, 137 colunas; mesmas colunas 1–46 do tipo 3):
//     1–9 NSR · 10 tipo · 11–34 data-hora "AAAA-MM-DDThh:mm:00-0300" · 35–46 CPF (12, zero à esquerda) · (tipo 3) 47–50 CRC-16
//   Portaria 1510, tipo 3 (34 colunas):
//     1–9 NSR · 10 tipo "3" · 11–18 data DDMMAAAA · 19–22 hora hhmm · 23–34 PIS (12, zero à esquerda)
// Detecção por linha: coluna 10 = tipo; coluna 21 = "T" → 671; senão comprimento ≥ 34 → 1510.
// Registro de empregado (tipo 5: inclusão "I", alteração "A" ou exclusão "E" no REP) → `empregados` (nome para o vínculo):
//   Portaria 671: 1–9 NSR · 10 "5" · 11–34 data-hora · 35 operação · 36–47 CPF (12) · 48–99 nome (52) · …
//   Portaria 1510: 1–9 NSR · 10 "5" · 11–18 data · 19–22 hora · 23 operação · 24–35 PIS (12) · 36–87 nome (52)
//   O tipo 5 continua contado em outros_registros; linha de empregado malformada só deixa de virar empregado.
// Demais tipos (1 cabeçalho, 2 empresa, 4 ajuste de relógio, 6 eventos, 9 trailer…) são contados e descartados.
// O CRC-16 e o hash SHA-256 não são validados (o equipamento é a fonte; a idempotência fica no banco por NSR).

const AFD_MAX_IGNORADAS_LISTADAS = 20;

function afdDigitos(texto) {
  return /^[0-9]+$/.test(texto);
}

function afdDataValida(ano, mes, dia, hora, minuto) {
  if (ano < 2000 || ano > 2099 || mes < 1 || mes > 12 || dia < 1 || dia > 31) return false;
  if (hora > 23 || minuto > 59) return false;
  const d = new Date(Date.UTC(ano, mes - 1, dia));
  return d.getUTCFullYear() === ano && d.getUTCMonth() === mes - 1 && d.getUTCDate() === dia;
}

function afdDocumento(campo12) {
  // CPF/PIS ocupam 12 posições com zero à esquerda; devolve 11 dígitos ou null.
  if (!afdDigitos(campo12)) return null;
  const excesso = campo12.slice(0, campo12.length - 11);
  if (!/^0*$/.test(excesso)) return null;
  const doc = campo12.slice(-11);
  if (/^0+$/.test(doc)) return null;
  return doc;
}

function afdDois(n) {
  return String(n).padStart(2, '0');
}

// Lê uma linha do AFD. Retorna { marcacao } | { ignorada: motivo } | { outro: tipo } | null (linha vazia).
function lerLinhaAfd(linhaBruta, tipos) {
  const tiposAceitos = tipos || ['3', '7'];
  const linha = String(linhaBruta ?? '').replace(/^﻿/, '').replace(/\s+$/, '');
  if (linha === '') return null;
  if (linha.length < 10) return { ignorada: 'linha curta demais' };
  const nsrTexto = linha.slice(0, 9);
  const tipo = linha.charAt(9);
  if (!afdDigitos(nsrTexto)) {
    // Cabeçalho/trailer de alguns equipamentos usam espaços/letras aqui; só reclamamos se parece marcação.
    if (tipo === '3' || tipo === '7') return { ignorada: 'NSR não numérico' };
    return { outro: tipo || '?' };
  }
  if (nsrTexto === '999999999' || tipo === '9') return { outro: '9' }; // trailer
  if (!tiposAceitos.includes(tipo)) return { outro: tipo };
  const nsr = Number(nsrTexto);
  if (nsr <= 0) return { ignorada: 'NSR zerado' };

  if (linha.charAt(20) === 'T') {
    // Portaria 671: data-hora em 11–34, CPF em 35–46.
    if (linha.length < 46) return { ignorada: 'registro 671 incompleto' };
    const dh = linha.slice(10, 34);
    const m = /^([0-9]{4})-([0-9]{2})-([0-9]{2})T([0-9]{2}):([0-9]{2}):([0-9]{2})([+-])([0-9]{2})([0-9]{2})$/.exec(dh);
    if (!m) return { ignorada: 'data-hora inválida' };
    const [ano, mes, dia, hora, minuto] = [m[1], m[2], m[3], m[4], m[5]].map(Number);
    if (!afdDataValida(ano, mes, dia, hora, minuto) || Number(m[6]) > 59) return { ignorada: 'data-hora inválida' };
    if (Number(m[8]) > 14 || Number(m[9]) > 59) return { ignorada: 'fuso inválido' };
    const cpf = afdDocumento(linha.slice(34, 46));
    if (!cpf) return { ignorada: 'CPF inválido' };
    return {
      marcacao: {
        id_externo: String(nsr),
        nsr,
        instante: `${m[1]}-${m[2]}-${m[3]}T${m[4]}:${m[5]}:${m[6]}${m[7]}${m[8]}:${m[9]}`,
        cpf,
      },
      layout: '671',
    };
  }

  if (tipo !== '3') return { ignorada: 'registro tipo 7 sem data-hora no layout 671' };
  if (linha.length < 34) return { ignorada: 'registro 1510 incompleto' };
  // Portaria 1510: data DDMMAAAA (11–18), hora hhmm (19–22), PIS (23–34). Sem fuso → instante_local.
  const data = linha.slice(10, 18);
  const hhmm = linha.slice(18, 22);
  if (!afdDigitos(data) || !afdDigitos(hhmm)) return { ignorada: 'data-hora inválida' };
  const dia = Number(data.slice(0, 2));
  const mes = Number(data.slice(2, 4));
  const ano = Number(data.slice(4, 8));
  const hora = Number(hhmm.slice(0, 2));
  const minuto = Number(hhmm.slice(2, 4));
  if (!afdDataValida(ano, mes, dia, hora, minuto)) return { ignorada: 'data-hora inválida' };
  const pis = afdDocumento(linha.slice(22, 34));
  if (!pis) return { ignorada: 'PIS inválido' };
  return {
    marcacao: {
      id_externo: String(nsr),
      nsr,
      instante_local: `${ano}-${afdDois(mes)}-${afdDois(dia)}T${afdDois(hora)}:${afdDois(minuto)}:00`,
      pis,
    },
    layout: '1510',
  };
}

// Lê um registro tipo 5 (empregado). Retorna {operacao, cpf|pis, nome, nsr} ou null se a linha não tiver o formato.
function lerEmpregadoAfd(linhaBruta) {
  const linha = String(linhaBruta ?? '').replace(/^\uFEFF/, '').replace(/\s+$/, '');
  if (linha.length < 36 || linha.charAt(9) !== '5' || !afdDigitos(linha.slice(0, 9))) return null;
  const nsr = Number(linha.slice(0, 9));
  if (linha.charAt(20) === 'T') {
    const operacao = linha.charAt(34);
    if (!'IAE'.includes(operacao) || operacao === '') return null;
    const cpf = afdDocumento(linha.slice(35, 47));
    if (!cpf) return null;
    const nome = linha.slice(47, 99).replace(/\s+/g, ' ').trim();
    return { nsr, operacao, cpf, nome: nome || null };
  }
  const operacao = linha.charAt(22);
  if (!'IAE'.includes(operacao) || operacao === '' || !afdDigitos(linha.slice(10, 22))) return null;
  const pis = afdDocumento(linha.slice(23, 35));
  if (!pis) return null;
  const nome = linha.slice(35, 87).replace(/\s+/g, ' ').trim();
  return { nsr, operacao, pis, nome: nome || null };
}

// lerAfd(texto) → { marcacoes, empregados, ignoradas, total_linhas, outros_registros, layouts }
//   marcacoes: [{id_externo, nsr, instante|instante_local, cpf|pis}] na ordem do arquivo, sem NSR repetido (fica o primeiro)
//   ignoradas: [{linha (1-based), motivo, conteudo}] — linhas que pareciam marcação mas estão corrompidas
//   empregados: [{cpf|pis, nome, operacao, nsr}] dos registros tipo 5, um por documento (fica o último do arquivo;
//     um nome vazio não apaga o nome visto antes)
//   outros_registros: { "<tipo>": quantidade } dos registros que não são marcação
function lerAfd(texto, opcoes) {
  const tipos = (opcoes && opcoes.tipos) || ['3', '7'];
  const linhas = String(texto ?? '').replace(/^﻿/, '').split(/\r\n|\n|\r/);
  const marcacoes = [];
  const ignoradas = [];
  const outros = {};
  const layouts = { '671': 0, '1510': 0 };
  const vistos = new Set();
  const empregados = new Map();
  let duplicadas = 0;
  let totalLinhas = 0;
  linhas.forEach((linha, i) => {
    const r = lerLinhaAfd(linha, tipos);
    if (r === null) return;
    totalLinhas += 1;
    if (r.outro !== undefined) {
      outros[r.outro] = (outros[r.outro] || 0) + 1;
      if (r.outro === '5') {
        const e = lerEmpregadoAfd(linha);
        if (e) {
          const chave = e.cpf ? `c${e.cpf}` : `p${e.pis}`;
          const antes = empregados.get(chave);
          if (antes) empregados.delete(chave);
          empregados.set(chave, { ...e, nome: e.nome || (antes && antes.nome) || null });
        }
      }
    } else if (r.ignorada) {
      ignoradas.push({ linha: i + 1, motivo: r.ignorada, conteudo: String(linha).slice(0, 60) });
    } else if (vistos.has(r.marcacao.id_externo)) {
      duplicadas += 1;
    } else {
      vistos.add(r.marcacao.id_externo);
      layouts[r.layout] += 1;
      marcacoes.push(r.marcacao);
    }
  });
  return {
    marcacoes,
    empregados: Array.from(empregados.values()),
    ignoradas,
    total_linhas: totalLinhas,
    outros_registros: outros,
    duplicadas,
    layouts,
  };
}

// Resumo pequeno para gravar em sync_execucoes.detalhes (no máximo 20 linhas ignoradas listadas).
function resumoAfd(leitura) {
  return {
    total_linhas: leitura.total_linhas,
    marcacoes: leitura.marcacoes.length,
    empregados: (leitura.empregados || []).length,
    ignoradas: leitura.ignoradas.length,
    duplicadas: leitura.duplicadas,
    layouts: leitura.layouts,
    outros_registros: leitura.outros_registros,
    exemplos_ignoradas: leitura.ignoradas.slice(0, AFD_MAX_IGNORADAS_LISTADAS),
  };
}

function deduplicarPorIdExterno(batidas) {
  const vistos = new Set();
  const saida = [];
  for (const b of batidas || []) {
    if (!b || b.id_externo === undefined || b.id_externo === null) continue;
    const chave = String(b.id_externo);
    if (vistos.has(chave)) continue;
    vistos.add(chave);
    saida.push(b);
  }
  return saida;
}

function emLotes(lista, tamanho) {
  const t = Math.max(1, Math.floor(tamanho || 1000));
  const lotes = [];
  for (let i = 0; i < (lista || []).length; i += t) lotes.push(lista.slice(i, i + t));
  return lotes;
}

// Recebe a saída do nó "Control iD · buscar batidas" e devolve os itens do próximo passo:
//   [{lote: [...], indice, total_lotes, afd_resumo}] ou, sem nada a gravar, [{sem_lote: true, afd_resumo}].
// REP: lê o AFD (busca.afd). Acesso: usa busca.batidas já mapeadas.
function separarLotes(busca, tamanhoLote) {
  let batidas = [];
  let afdResumo = null;
  if (busca && busca.ok) {
    if (typeof busca.afd === 'string') {
      const leitura = lerAfd(busca.afd);
      batidas = leitura.marcacoes;
      afdResumo = resumoAfd(leitura);
    } else if (Array.isArray(busca.batidas)) {
      batidas = busca.batidas;
    }
  }
  const lotes = emLotes(deduplicarPorIdExterno(batidas), tamanhoLote || 1000);
  if (lotes.length === 0) return [{ sem_lote: true, afd_resumo: afdResumo }];
  return lotes.map((lote, indice) => ({ lote, indice, total_lotes: lotes.length, afd_resumo: afdResumo }));
}

// @lib comum/lib/supabase.mjs
// Chamadas ao Supabase (PostgREST) e despacho da fila "Sincronizar agora" — funções puras, sem import.
// Usada nos nós Code dos workflows (cópia marcada com `// @lib comum/lib/supabase.mjs`, conferida por `npm run n8n:verificar`).
// O transporte HTTP é injetado (`http(req) → Promise<{status, headers, corpo}>`): no N8N vem de `criarHttpN8n(this.helpers)`,
// nos testes de `criarHttpFetch(fetch)`.

const NOMES_WORKFLOWS = {
  CONTROLID_USUARIOS: 'MDG · Control iD · Importar usuários',
  CONTROLID_BATIDAS: 'MDG · Control iD · Importar batidas',
  CONTROLID_EXPORTAR: 'MDG · Control iD · Exportar funcionários',
  ZIG_IMPORTAR: 'MDG · Zig · Importar',
  TAGME_IMPORTAR: 'MDG · Tagme · Importar',
  RHID_IMPORTAR: 'MDG · RHiD · Importar',
  EXPORTAR_FECHAMENTO: 'MDG · Exportar fechamento CSV',
  SINCRONIZAR_AGORA: 'MDG · Sincronizar agora (fila)',
  AGENDADOR: 'MDG · Agendador',
  ROTINA_DIARIA: 'MDG · Rotina diária',
  ERROS: 'MDG · Tratador de erros',
}

/** Variável de ambiente que guarda o id (no N8N) de cada subfluxo. */
const VARIAVEIS_SUBFLUXOS = {
  CONTROLID_USUARIOS: 'MDG_WF_CONTROLID_USUARIOS',
  CONTROLID_BATIDAS: 'MDG_WF_CONTROLID_BATIDAS',
  CONTROLID_EXPORTAR: 'MDG_WF_CONTROLID_EXPORTAR',
  ZIG_IMPORTAR: 'MDG_WF_ZIG_IMPORTAR',
  TAGME_IMPORTAR: 'MDG_WF_TAGME_IMPORTAR',
  RHID_IMPORTAR: 'MDG_WF_RHID_IMPORTAR',
  EXPORTAR_FECHAMENTO: 'MDG_WF_EXPORTAR_FECHAMENTO',
}

/** Tipo de `sync_execucoes` aberto por cada workflow (usado pelo tratador de erros). */
const TIPO_EXECUCAO_POR_WORKFLOW = {
  'MDG · Control iD · Importar usuários': 'controlid_usuarios',
  'MDG · Control iD · Importar batidas': 'controlid_batidas',
  'MDG · Control iD · Exportar funcionários': 'controlid_exportar_usuarios',
  'MDG · Zig · Importar': 'zig_importar',
  'MDG · Tagme · Importar': 'tagme_importar',
  'MDG · RHiD · Importar': 'rhid_batidas', // abre também rhid_pessoas (escopos tudo/funcionarios)
  'MDG · Exportar fechamento CSV': 'exportar_fechamento',
  'MDG · Rotina diária': 'apurar_ponto',
}

/**
 * Lê uma variável tentando cada fonte em ordem (ex.: `[() => $env, () => $vars]`). Fonte que lança erro
 * (ex.: `$env` bloqueado no N8N Cloud) é pulada. Valor vazio conta como ausente.
 */
function lerVariavel(nome, fontes, padrao) {
  for (const fonte of fontes || []) {
    try {
      const obj = typeof fonte === 'function' ? fonte() : fonte
      const v = obj ? obj[nome] : undefined
      if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim()
    } catch (e) {
      // fonte indisponível — tenta a próxima
    }
  }
  return padrao
}

/** Configuração do Supabase a partir das variáveis. Lança erro claro se faltar algo. */
function configSupabase(fontes) {
  const url = lerVariavel('SUPABASE_URL', fontes)
  const chave = lerVariavel('SUPABASE_SERVICE_ROLE_KEY', fontes)
  if (!url) throw new Error('Variável SUPABASE_URL não configurada no N8N')
  if (!chave) throw new Error('Variável SUPABASE_SERVICE_ROLE_KEY não configurada no N8N')
  return { url: url.replace(/\/+$/, ''), chave }
}

function cabecalhosSupabase(chave) {
  return { apikey: chave, Authorization: `Bearer ${chave}`, 'Content-Type': 'application/json', Accept: 'application/json' }
}

/** Monta a requisição `POST {url}/rest/v1/rpc/<nome>` com o corpo `{p_...}` (§12.2). */
function montarChamadaRpc(cfg, nome, args, timeoutMs) {
  if (!/^[a-z_][a-z0-9_]*$/.test(nome || '')) throw new Error(`Nome de RPC inválido: ${nome}`)
  const corpo = {}
  for (const [k, v] of Object.entries(args || {})) if (v !== undefined) corpo[k] = v
  return {
    method: 'POST',
    url: `${cfg.url}/rest/v1/rpc/${nome}`,
    headers: cabecalhosSupabase(cfg.chave),
    corpo,
    timeoutMs: timeoutMs || 60000,
  }
}

/** 408, 425, 429 e 5xx valem nova tentativa; demais 4xx não. `null` (falha de rede/timeout) também vale. */
function deveRetentar(status) {
  if (status === null || status === undefined) return true
  return status === 408 || status === 425 || status === 429 || status >= 500
}

/** Lê `Retry-After` (segundos ou data HTTP) em ms; null se ausente/inválido. */
function lerRetryAfter(headers, agoraMs) {
  if (!headers) return null
  let v = headers['retry-after'] ?? headers['Retry-After']
  if (v === undefined || v === null || v === '') return null
  v = String(v).trim()
  if (/^\d+(\.\d+)?$/.test(v)) return Math.round(Number(v) * 1000)
  const data = Date.parse(v)
  if (Number.isNaN(data)) return null
  return Math.max(0, data - (agoraMs ?? Date.now()))
}

/** Espera antes da tentativa `n+1` (n = tentativas já feitas, ≥ 1): base × 2^(n−1), respeitando Retry-After, limitado. */
function esperaAntesDaProxima(n, opcoes) {
  const base = opcoes?.esperaMs ?? 5000
  const max = opcoes?.maxEsperaMs ?? 60000
  const exponencial = base * Math.pow(2, Math.max(0, n - 1))
  const pedido = opcoes?.retryAfterMs
  return Math.min(max, Math.max(exponencial, pedido ?? 0))
}

class ErroHttp extends Error {
  constructor(mensagem, detalhes) {
    super(mensagem)
    this.name = 'ErroHttp'
    this.status = detalhes?.status ?? null
    this.corpo = detalhes?.corpo
    this.tentativas = detalhes?.tentativas ?? 1
    this.url = detalhes?.url
  }
}

/** Remove segredos de uma URL antes de aparecer em mensagem de erro. */
function urlSegura(url) {
  return String(url || '').replace(/([?&](session|token|apikey|key)=)[^&]*/gi, '$1***')
}

function resumoCorpo(corpo) {
  if (corpo === undefined || corpo === null || corpo === '') return ''
  if (typeof corpo === 'string') return corpo.slice(0, 300)
  if (typeof corpo === 'object') {
    const m = corpo.message || corpo.mensagem || corpo.error || corpo.erro || corpo.hint
    if (m) return String(m).slice(0, 300)
    try { return JSON.stringify(corpo).slice(0, 300) } catch (e) { return '' }
  }
  return String(corpo).slice(0, 300)
}

/**
 * Executa `req` com retentativa e *backoff* exponencial em falha de rede, timeout, 408/425/429/5xx.
 * opcoes: { tentativas = 3, esperaMs = 5000, maxEsperaMs = 60000, dormir(ms), rotulo }
 * Retorna `{ status, headers, corpo, tentativas }` (2xx). Lança `ErroHttp` (com `.tentativas`) se esgotar ou se 4xx.
 */
async function requisitarComRetentativa(http, req, opcoes) {
  const tentativas = Math.max(1, opcoes?.tentativas ?? 3)
  const dormir = opcoes?.dormir || ((ms) => new Promise((ok) => setTimeout(ok, ms)))
  const rotulo = opcoes?.rotulo || `${req.method} ${urlSegura(req.url).split('?')[0]}`
  let ultimo = null
  for (let n = 1; n <= tentativas; n++) {
    let resposta = null
    let erroRede = null
    try {
      resposta = await http(req)
    } catch (e) {
      erroRede = e
    }
    if (resposta && resposta.status >= 200 && resposta.status < 300) return { ...resposta, tentativas: n }
    const status = resposta ? resposta.status : null
    ultimo = new ErroHttp(
      resposta
        ? `${rotulo}: HTTP ${status}${resumoCorpo(resposta.corpo) ? ' — ' + resumoCorpo(resposta.corpo) : ''}`
        : `${rotulo}: ${erroRede && erroRede.message ? erroRede.message : 'falha de rede'}`,
      { status, corpo: resposta ? resposta.corpo : undefined, tentativas: n, url: urlSegura(req.url) },
    )
    if (!deveRetentar(status) || n === tentativas) break
    await dormir(esperaAntesDaProxima(n, { esperaMs: opcoes?.esperaMs, maxEsperaMs: opcoes?.maxEsperaMs, retryAfterMs: resposta ? lerRetryAfter(resposta.headers) : null }))
  }
  if (tentativas > 1 && ultimo.tentativas > 1) ultimo.message += ` (após ${ultimo.tentativas} tentativas)`
  throw ultimo
}

/** Chama uma RPC (3 tentativas, 5 s de base — §12.2) e devolve o corpo já interpretado. */
async function chamarRpc(http, cfg, nome, args, opcoes) {
  const req = montarChamadaRpc(cfg, nome, args, opcoes?.timeoutMs)
  const r = await requisitarComRetentativa(http, req, { tentativas: 3, esperaMs: 5000, rotulo: `RPC ${nome}`, ...(opcoes || {}) })
  return r.corpo === '' ? null : r.corpo
}

/** Lê linhas de uma tabela via PostgREST (service_role). `filtros` já no formato do PostgREST (ex.: {status: 'eq.executando'}). */
async function selecionar(http, cfg, tabela, filtros, opcoes) {
  const qs = Object.entries(filtros || {}).map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`).join('&')
  const req = { method: 'GET', url: `${cfg.url}/rest/v1/${tabela}${qs ? '?' + qs : ''}`, headers: cabecalhosSupabase(cfg.chave), timeoutMs: 30000 }
  const r = await requisitarComRetentativa(http, req, { tentativas: 3, esperaMs: 5000, rotulo: `GET ${tabela}`, ...(opcoes || {}) })
  return Array.isArray(r.corpo) ? r.corpo : []
}

function mensagemDeErro(e) {
  if (!e) return 'Erro desconhecido'
  if (typeof e === 'string') return e.slice(0, 1000)
  const m = e.message || e.description || e.erro || (e.error && (e.error.message || e.error)) || String(e)
  return String(m).slice(0, 1000)
}

/** Adaptador para `this.helpers.httpRequest` do nó Code do N8N. */
function criarHttpN8n(helpers) {
  return async (req) => {
    const r = await helpers.httpRequest({
      method: req.method,
      url: req.url,
      headers: req.headers,
      body: req.corpo,
      json: req.texto ? false : true,
      timeout: req.timeoutMs || 60000,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
    })
    let corpo = r.body
    if (!req.texto && typeof corpo === 'string' && corpo !== '') {
      try { corpo = JSON.parse(corpo) } catch (e) { /* mantém texto */ }
    }
    return { status: r.statusCode, headers: r.headers || {}, corpo }
  }
}

/** Adaptador para `fetch` (Node ≥ 18) — testes e uso local. */
function criarHttpFetch(fetchFn) {
  return async (req) => {
    const controle = new AbortController()
    const t = setTimeout(() => controle.abort(), req.timeoutMs || 60000)
    try {
      const r = await fetchFn(req.url, {
        method: req.method,
        headers: req.headers,
        body: req.corpo === undefined ? undefined : typeof req.corpo === 'string' ? req.corpo : JSON.stringify(req.corpo),
        signal: controle.signal,
      })
      const texto = await r.text()
      let corpo = texto
      if (!req.texto && texto !== '') {
        try { corpo = JSON.parse(texto) } catch (e) { /* mantém texto */ }
      }
      const headers = {}
      r.headers.forEach((v, k) => { headers[k.toLowerCase()] = v })
      return { status: r.status, headers, corpo }
    } catch (e) {
      if (e && e.name === 'AbortError') throw new Error(`tempo esgotado (${req.timeoutMs || 60000} ms)`)
      throw e
    } finally {
      clearTimeout(t)
    }
  }
}

// ----------------------------------------------------------------------------------------------- despacho (§12.3)

/** Subfluxos (em ordem) de uma combinação tipo × escopo. `envioAtivo` = parametros.envio.ativo do equipamento (adendo A.5). */
function subfluxosDe(tipo, escopo, envioAtivo) {
  const controlid = tipo === 'controlid_acesso' || tipo === 'controlid_rep'
  if (escopo === 'exportar_fechamento') return ['EXPORTAR_FECHAMENTO']
  if (tipo === 'zig') return escopo === 'tudo' || escopo === 'vendas' ? ['ZIG_IMPORTAR'] : null
  if (tipo === 'tagme') return escopo === 'tudo' || escopo === 'reservas' ? ['TAGME_IMPORTAR'] : null
  if (tipo === 'rhid') return ['tudo', 'funcionarios', 'batidas'].includes(escopo) ? ['RHID_IMPORTAR'] : null
  if (controlid) {
    if (escopo === 'tudo') return envioAtivo ? ['CONTROLID_USUARIOS', 'CONTROLID_EXPORTAR', 'CONTROLID_BATIDAS'] : ['CONTROLID_USUARIOS', 'CONTROLID_BATIDAS']
    if (escopo === 'funcionarios') return ['CONTROLID_USUARIOS']
    if (escopo === 'batidas') return ['CONTROLID_BATIDAS']
    if (escopo === 'exportar_funcionarios') return ['CONTROLID_EXPORTAR']
  }
  return null
}

/** Item de entrada de todo subfluxo (§12.3). */
function entradaSubfluxo(s, gatilho) {
  return {
    integracao_id: s.integracao_id ?? null,
    empresa_id: s.empresa_id ?? null,
    tipo: s.integracao_tipo ?? s.tipo ?? null,
    escopo: s.escopo ?? 'tudo',
    gatilho: gatilho || (s.solicitacao_id ? 'manual' : 'agendado'),
    solicitacao_id: s.solicitacao_id ?? null,
    data_inicio: s.data_inicio ?? null,
    data_fim: s.data_fim ?? null,
    parametros: s.parametros && typeof s.parametros === 'object' ? s.parametros : {},
  }
}

/**
 * Expande uma solicitação da fila (linha de `ingestao_sync_pegar_solicitacoes`) — ou uma integração vencida do agendador —
 * em passos ordenados. Cada passo é um item: os campos da entrada do subfluxo no topo + `_despacho` com o controle.
 * `ids` = { ZIG_IMPORTAR: '<id do workflow>', ... }. `envioAtivo` só importa para Control iD com escopo `tudo`.
 */
function planejarDespacho(s, ids, opcoes) {
  const gatilho = opcoes?.gatilho
  const entrada = entradaSubfluxo(s, gatilho)
  const chave = s.solicitacao_id || `${entrada.integracao_id}|${entrada.escopo}`
  const base = (ordem, total, extra) => ({ ...entrada, _despacho: { chave, solicitacao_id: entrada.solicitacao_id, ordem, total, ...extra } })
  if (entrada.escopo === 'apurar_ponto') return [base(1, 1, { acao: 'apurar_ponto' })]
  if (entrada.escopo === 'exportar_fechamento' && !(entrada.parametros && entrada.parametros.fechamento_id)) {
    return [base(1, 1, { acao: 'invalido', erro: 'Solicitação de exportação sem fechamento_id' })]
  }
  const lista = subfluxosDe(entrada.tipo, entrada.escopo, opcoes?.envioAtivo === true)
  if (!lista) return [base(1, 1, { acao: 'invalido', erro: `Escopo "${entrada.escopo}" não se aplica a integração do tipo "${entrada.tipo}"` })]
  // Falta o id de algum subfluxo → a solicitação inteira vira um único passo inválido (nada roda pela metade).
  const faltando = lista.find((nome) => !(ids && ids[nome]))
  if (faltando) {
    return [base(1, 1, { acao: 'invalido', subfluxo: faltando, workflow_nome: NOMES_WORKFLOWS[faltando], tipo_execucao: TIPO_EXECUCAO_POR_WORKFLOW[NOMES_WORKFLOWS[faltando]],
      erro: `Variável ${VARIAVEIS_SUBFLUXOS[faltando]} não configurada no N8N (id do workflow "${NOMES_WORKFLOWS[faltando]}")` })]
  }
  return lista.map((nome, i) => base(i + 1, lista.length, { acao: 'subfluxo', subfluxo: nome, workflow_id: String(ids[nome]), workflow_nome: NOMES_WORKFLOWS[nome] }))
}

/** `parametros.envio.ativo` de uma configuração de integração (adendo de envio ao Control iD). */
function envioAtivo(config) {
  return !!(config && config.parametros && config.parametros.envio && config.parametros.envio.ativo === true)
}

/** Precisa ler a configuração da integração para despachar? (só Control iD com escopo `tudo`, por causa do envio). */
function precisaConfigParaDespacho(s) {
  const tipo = s.integracao_tipo ?? s.tipo
  return (tipo === 'controlid_acesso' || tipo === 'controlid_rep') && (s.escopo ?? 'tudo') === 'tudo' && !!s.integracao_id
}

/** Ids dos subfluxos a partir das variáveis. */
function idsSubfluxos(fontes) {
  const ids = {}
  for (const [nome, variavel] of Object.entries(VARIAVEIS_SUBFLUXOS)) ids[nome] = lerVariavel(variavel, fontes)
  return ids
}

/** Normaliza a saída de um subfluxo (ou o erro do nó Execute Workflow) para `{status, lidos, gravados, ignorados, erro, execucao_ids}`. */
function normalizarSaida(json) {
  const j = json || {}
  if (j.error) {
    const erro = typeof j.error === 'string' ? j.error : mensagemDeErro(j.error)
    return { status: 'erro', lidos: 0, gravados: 0, ignorados: 0, erro, execucao_ids: [] }
  }
  const status = ['sucesso', 'parcial', 'erro'].includes(j.status) ? j.status : 'erro'
  return {
    status,
    lidos: Number(j.lidos) || 0,
    gravados: Number(j.gravados) || 0,
    ignorados: Number(j.ignorados) || 0,
    erro: j.erro ?? (j.status ? null : 'Subfluxo não devolveu status'),
    execucao_ids: Array.isArray(j.execucao_ids) ? j.execucao_ids.filter(Boolean) : j.execucao_id ? [j.execucao_id] : [],
  }
}

/**
 * Junta os resultados dos passos de cada solicitação → `[{solicitacao_id, status: 'concluida'|'erro', mensagem, execucao_id}]`.
 * `passos` = [{ _despacho, resultado: saída normalizada }]. Qualquer passo `erro` → solicitação `erro`.
 */
function consolidarSolicitacoes(passos) {
  const grupos = new Map()
  for (const p of passos) {
    const d = p._despacho || {}
    if (!d.solicitacao_id) continue
    if (!grupos.has(d.solicitacao_id)) grupos.set(d.solicitacao_id, [])
    grupos.get(d.solicitacao_id).push(p)
  }
  const saida = []
  for (const [solicitacao_id, lista] of grupos) {
    lista.sort((a, b) => (a._despacho.ordem || 0) - (b._despacho.ordem || 0))
    const resultados = lista.map((p) => p.resultado || { status: 'erro', erro: 'Sem resultado' })
    const erros = lista.filter((p, i) => resultados[i].status === 'erro')
    const parciais = resultados.filter((r) => r.status === 'parcial').length
    const tot = resultados.reduce((a, r) => ({ lidos: a.lidos + (r.lidos || 0), gravados: a.gravados + (r.gravados || 0), ignorados: a.ignorados + (r.ignorados || 0) }), { lidos: 0, gravados: 0, ignorados: 0 })
    const ids = resultados.flatMap((r) => r.execucao_ids || [])
    let mensagem
    if (erros.length) {
      mensagem = erros.map((p) => `${p._despacho.workflow_nome || p._despacho.subfluxo || p._despacho.acao}: ${p.resultado?.erro || p._despacho.erro || 'erro'}`).join(' | ')
    } else {
      mensagem = `${tot.lidos} lidos, ${tot.gravados} gravados, ${tot.ignorados} ignorados${parciais ? ` (${parciais} parcial)` : ''}`
    }
    saida.push({ solicitacao_id, status: erros.length ? 'erro' : 'concluida', mensagem: mensagem.slice(0, 1000), execucao_id: ids[ids.length - 1] || null })
  }
  return saida
}

// ----------------------------------------------------------------------------------------------- sync_execucoes

/**
 * Abre uma `sync_execucoes`, roda `trabalho(execucaoId)` e fecha com o resultado. `trabalho` devolve
 * `{status?, lidos, gravados, ignorados, detalhes?, tentativas?, erro?}`; exceção → fecha com `erro` e devolve a saída de erro.
 * Saída no formato do §12.3: `{execucao_ids, status, lidos, gravados, ignorados, erro}` (+ `retorno` do trabalho).
 */
async function comExecucao(http, cfg, abertura, trabalho) {
  const execucaoId = await chamarRpc(http, cfg, 'ingestao_sync_iniciar', {
    p_tipo: abertura.tipo,
    p_gatilho: abertura.gatilho === 'manual' || abertura.gatilho === 'webhook' ? abertura.gatilho : 'agendado',
    p_workflow: abertura.workflow,
    p_empresa: abertura.empresa_id ?? null,
    p_integracao: abertura.integracao_id ?? null,
    p_solicitacao: abertura.solicitacao_id ?? null,
    p_periodo_inicio: abertura.periodo_inicio ?? null,
    p_periodo_fim: abertura.periodo_fim ?? null,
    p_n8n_execution_id: abertura.n8n_execution_id != null ? String(abertura.n8n_execution_id) : null,
  })
  let r
  try {
    r = (await trabalho(execucaoId)) || {}
  } catch (e) {
    r = { status: 'erro', erro: mensagemDeErro(e), tentativas: e && e.tentativas ? e.tentativas : 1 }
  }
  const status = ['sucesso', 'parcial', 'erro'].includes(r.status) ? r.status : 'sucesso'
  const saida = {
    execucao_ids: [execucaoId],
    status,
    lidos: Number(r.lidos) || 0,
    gravados: Number(r.gravados) || 0,
    ignorados: Number(r.ignorados) || 0,
    erro: status === 'sucesso' ? null : r.erro || null,
  }
  await chamarRpc(http, cfg, 'ingestao_sync_finalizar', {
    p_execucao: execucaoId,
    p_status: status,
    p_lidos: saida.lidos,
    p_gravados: saida.gravados,
    p_ignorados: saida.ignorados,
    p_erro: saida.erro,
    p_detalhes: r.detalhes || {},
    p_tentativas: Math.max(1, Number(r.tentativas) || 1),
  })
  if (r.retorno !== undefined) saida.retorno = r.retorno
  return saida
}

// @lib rhid/lib/rhid.mjs
// Integração RHiD (nuvem da Control iD) pela API oficial — docs/referencias/rhid-swagger.json e docs/CONTRATO-ADENDO-rhid.md.
// Funções puras, sem import. Copiada no nó Code do workflow "MDG · RHiD · Importar" com `// @lib rhid/lib/rhid.mjs`,
// logo depois de `// @lib controlid/lib/afd.mjs` (o leitor de AFD `lerAfd` entra por `deps.lerAfd`) e de
// `// @lib comum/lib/supabase.mjs` (transporte, RPC e sync_execucoes). Conferida por `npm run n8n:verificar`.
//
// Por que RHiD: o relógio da loja (iDClass, Portaria 671) não é alcançável pela rede, mas sincroniza com o RHiD; a API do
// RHiD devolve as pessoas e o AFD 671 de cada equipamento.
//
//   POST {base}/login  {email, password, domain?}           → {accessToken}   (demais: Authorization: Bearer <token>; 401 → novo login)
//   GET  {base}/person                                       → {totalRecords, records: [PersonDTO]} (sem paginação de verdade)
//   GET  {base}/device                                       → {totalRecords, records: [DeviceDTO]} (model 1=REP-C, 2=REP-A, 3=Outros, 5=REP-P)
//   GET  {base}/report/afd/download671?idEquipamento=&dataIni=&dataFinal=&nsrInicial=&limit=   → texto AFD 671 (≤ 90 dias, limit ≤ 50000)
//        REP-P: idEquipamento = idCompany + 99000000
//   GET  {base}/report/afd_coletor_marcacao/download671?…   → AFD das marcações do coletor do REP-P (mesmas regras)
//
// Integração tipo 'rhid':
//   segredos   { email, senha, dominio? }   (crie no RHiD um usuário só para a integração, com leitura de pessoas e relatórios)
//   parametros { equipamentos: [] (ids; vazio = REPs do cliente + REP-P), incluir_rep_p: true, dias_retroativos: 7,
//                importar_pessoas: true, url_base?: (padrão RHID_BASE_PADRAO ou variável RHID_BASE_URL), limite_afd?: 50000 }
//   cursor     { nsr_por_equipamento: { "<chave>": ultimo_nsr } }   chave = id do equipamento; coletor do REP-P = "c<id>"
//              horarios_em: último envio dos horários previstos (§R.9; parametros importar_horarios, horarios_intervalo_minutos,
//              dias_horarios)
//   GET  {base}/apuracao_ponto?idPerson=&dataIni=&dataFinal=  → string JSON: um objeto por dia (horasUteis, folga, isHoliday…)
// Nunca registra senha nem token (nem em mensagem de erro, nem em sync_execucoes.detalhes).

const RHID_BASE_PADRAO = 'https://www.rhid.com.br/v2/api.svc'
const RHID_MAX_DIAS = 90
const RHID_LIMITE_AFD = 50000
const RHID_DESLOCAMENTO_REP_P = 99000000
const RHID_TAMANHO_LOTE = 1000
/** Modelos do RHiD que geram AFD por id próprio (1 = REP-C, 2 = REP-A). REP-P (5) usa idCompany + 99000000. */
const RHID_MODELOS_REP = [1, 2]

function preenchidoRhid(v) {
  return v !== undefined && v !== null && !(typeof v === 'string' && v.trim() === '')
}

function somarDiasRhid(iso, n) {
  return new Date(Date.parse(iso + 'T00:00:00Z') + n * 86400000).toISOString().slice(0, 10)
}

function dataValidaRhid(iso) {
  if (typeof iso !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(iso)) return false
  const d = new Date(iso + 'T00:00:00Z')
  return !Number.isNaN(d.getTime()) && d.toISOString().slice(0, 10) === iso
}

function inteiroRhid(v, padrao, min, max) {
  const n = v === undefined || v === null || v === '' ? padrao : Math.trunc(Number(v))
  if (!Number.isFinite(n)) return padrao
  return Math.max(min, Math.min(max, n))
}

/** Confere tipo e credenciais; devolve a URL base (sem barra final). */
function validarConfigRhid(config, baseVariavel) {
  if (!config || config.tipo !== 'rhid') throw new Error('Tipo de integração incompatível')
  const s = config.segredos || {}
  if (!preenchidoRhid(s.email) || !preenchidoRhid(s.senha)) {
    throw new Error('Credencial do RHiD não configurada (Integrações → RHiD: e-mail e senha do usuário de integração)')
  }
  const p = config.parametros || {}
  const base = (preenchidoRhid(p.url_base) && p.url_base) || (preenchidoRhid(baseVariavel) && baseVariavel) || RHID_BASE_PADRAO
  if (!/^https?:\/\//.test(String(base))) throw new Error(`URL base do RHiD inválida: ${base}`)
  return String(base).replace(/\/+$/, '')
}

/** O que esta execução faz: pessoas (tudo/funcionarios, se importar_pessoas) e/ou batidas (tudo/batidas). */
function planoRhid(entrada, config) {
  const escopo = (entrada && entrada.escopo) || 'tudo'
  const p = (config && config.parametros) || {}
  return {
    pessoas: (escopo === 'tudo' && p.importar_pessoas !== false) || escopo === 'funcionarios',
    batidas: escopo === 'tudo' || escopo === 'batidas',
  }
}

/** Requisição de login (o corpo leva a senha: nunca registrar `req`). */
function requisicaoLoginRhid(base, segredos, timeoutMs) {
  const corpo = { email: String(segredos.email).trim(), password: String(segredos.senha) }
  if (preenchidoRhid(segredos.dominio)) corpo.domain = String(segredos.dominio).trim()
  return { method: 'POST', url: `${base}/login`, headers: { 'Content-Type': 'application/json', Accept: 'application/json' }, corpo, timeoutMs: timeoutMs || 60000 }
}

function corpoJsonRhid(corpo) {
  if (typeof corpo === 'string') {
    const t = corpo.trim()
    if (t.startsWith('{') || t.startsWith('[') || t.startsWith('"')) {
      try { return JSON.parse(t) } catch (e) { return corpo }
    }
  }
  return corpo
}

/** accessToken da resposta do login; erros do RHiD viram mensagem clara (sem ecoar credenciais). */
function tokenDoLoginRhid(corpo) {
  const c = corpoJsonRhid(corpo) || {}
  if (c.expiredPassword === true) throw new Error('RHiD: a senha do usuário de integração expirou — troque no RHiD e atualize em Integrações')
  if (c.customerBlocked === true) throw new Error('RHiD: cliente bloqueado no RHiD')
  if (c.isPerson === true) throw new Error('RHiD: o login é de um colaborador (Person); use um usuário operador com leitura de pessoas e relatórios')
  if (!preenchidoRhid(c.accessToken)) throw new Error(`RHiD: login sem token${c.error ? ` (${String(c.error).slice(0, 120)})` : ''}`)
  return String(c.accessToken)
}

function cabecalhosRhid(token) {
  return { Authorization: `Bearer ${token}`, Accept: 'application/json, text/plain, */*' }
}

/** URL com query (valores vazios saem). */
function urlRhid(base, caminho, params) {
  const qs = Object.entries(params || {})
    .filter(([, v]) => v !== undefined && v !== null && v !== '')
    .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(String(v))}`)
    .join('&')
  return `${base}${caminho}${qs ? '?' + qs : ''}`
}

/** `records` de PersonResult/DeviceResult (aceita a lista na raiz e corpo em texto JSON). */
function registrosRhid(corpo, rotulo) {
  const c = corpoJsonRhid(corpo)
  if (Array.isArray(c)) return c
  if (c && typeof c === 'object' && Array.isArray(c.records)) return c.records
  if (c && typeof c === 'object' && (c.error || c.code)) throw new Error(`RHiD ${rotulo}: ${String(c.error || c.code).slice(0, 200)}`)
  throw new Error(`RHiD ${rotulo}: resposta sem "records"`)
}

/** Texto do AFD: a API declara application/json, então o texto pode vir como string JSON ("…"). */
function textoAfdRhid(corpo) {
  if (corpo === null || corpo === undefined) return ''
  if (typeof corpo === 'string') {
    const t = corpo.trim()
    if (t.startsWith('"')) {
      try { const v = JSON.parse(t); if (typeof v === 'string') return v } catch (e) { /* texto cru */ }
    }
    if (t.startsWith('{')) {
      const v = corpoJsonRhid(t)
      if (v && typeof v === 'object') throw new Error(`RHiD AFD: ${String(v.error || v.message || JSON.stringify(v)).slice(0, 200)}`)
    }
    return corpo
  }
  if (typeof corpo === 'object') {
    if (typeof corpo.data === 'string') return corpo.data
    throw new Error(`RHiD AFD: ${String(corpo.error || corpo.message || JSON.stringify(corpo)).slice(0, 200)}`)
  }
  return String(corpo)
}

/** idCompany distintos (pessoas e equipamentos), em ordem. */
function empresasRhid(pessoas, dispositivos) {
  const ids = new Set()
  for (const p of pessoas || []) if (p && Number(p.idCompany) > 0) ids.add(Number(p.idCompany))
  for (const d of dispositivos || []) {
    if (!d) continue
    if (Number(d.linkedCompanyId) > 0) ids.add(Number(d.linkedCompanyId))
    for (const c of d.listOfLinkedCompanyIds || []) if (Number(c) > 0) ids.add(Number(c))
  }
  return [...ids].sort((a, b) => a - b)
}

/**
 * Equipamentos a baixar: [{chave, id, nome, rota: 'afd' | 'coletor', automatico}].
 * `parametros.equipamentos` com ids → só esses (id ≥ 99000000 = REP-P: também o coletor, se incluir_rep_p).
 * Vazio → REPs do cliente (model 1/2) e, com incluir_rep_p, o REP-P de cada idCompany (AFD + coletor).
 */
function alvosRhid(dispositivos, parametros, empresas) {
  const p = parametros || {}
  const repP = p.incluir_rep_p !== false
  const lista = []
  const vistos = new Set()
  const add = (id, nome, rota, automatico) => {
    const chave = rota === 'coletor' ? `c${id}` : String(id)
    if (vistos.has(chave)) return
    vistos.add(chave)
    lista.push({ chave, id: Number(id), nome, rota, automatico })
  }
  const nomes = new Map((dispositivos || []).filter(Boolean).map((d) => [Number(d.id), d.name || d.serial || `Equipamento ${d.id}`]))
  const explicitos = (Array.isArray(p.equipamentos) ? p.equipamentos : [])
    .map((x) => (x && typeof x === 'object' ? x.id : x))
    .map((x) => Math.trunc(Number(String(x).trim())))
    .filter((x) => Number.isFinite(x) && x > 0)
  if (explicitos.length) {
    for (const id of explicitos) {
      const ehRepP = id >= RHID_DESLOCAMENTO_REP_P
      const nome = nomes.get(id) || (ehRepP ? `REP-P (empresa ${id - RHID_DESLOCAMENTO_REP_P})` : `Equipamento ${id}`)
      add(id, nome, 'afd', false)
      if (ehRepP && repP) add(id, `${nome} · coletor`, 'coletor', false)
    }
    return lista
  }
  for (const d of dispositivos || []) {
    if (d && RHID_MODELOS_REP.includes(Number(d.model)) && Number(d.id) > 0) add(Number(d.id), nomes.get(Number(d.id)), 'afd', false)
  }
  if (repP) {
    for (const c of empresas || []) {
      const id = RHID_DESLOCAMENTO_REP_P + Number(c)
      add(id, `REP-P (empresa ${c})`, 'afd', true)
      add(id, `REP-P (empresa ${c}) · coletor`, 'coletor', true)
    }
  }
  return lista
}

/**
 * Janela e NSR inicial de um equipamento. `hoje` = dia de trabalho atual; o fim vai até hoje + 1 (batidas depois da meia-noite).
 *   pedido com data_inicio/data_fim → as datas pedidas (fim + 1), sem NSR (reimportação idempotente)
 *   com cursor                      → nsrInicial = cursor + 1, janela máxima (90 dias até hoje + 1)
 *   sem cursor                      → [hoje − dias_retroativos, hoje + 1]
 */
function janelaRhid(entrada, config, ultimoNsr) {
  const hoje = config && config.dia_trabalho_atual
  if (!dataValidaRhid(hoje)) throw new Error('Configuração sem dia_trabalho_atual')
  const p = (config && config.parametros) || {}
  const fimPadrao = somarDiasRhid(hoje, 1)
  let ini = entrada && entrada.data_inicio
  let fim = entrada && entrada.data_fim
  if (ini || fim) {
    ini = ini || fim
    fim = fim || ini
    if (!dataValidaRhid(ini) || !dataValidaRhid(fim) || ini > fim) throw new Error(`Período inválido: ${ini} a ${fim}`)
    fim = somarDiasRhid(fim, 1)
    if (somarDiasRhid(ini, RHID_MAX_DIAS - 1) < fim) ini = somarDiasRhid(fim, -(RHID_MAX_DIAS - 1))
    return { dataIni: ini, dataFinal: fim, nsrInicial: null, modo: 'periodo' }
  }
  if (ultimoNsr !== undefined && ultimoNsr !== null && Number.isFinite(Number(ultimoNsr))) {
    return { dataIni: somarDiasRhid(fimPadrao, -(RHID_MAX_DIAS - 1)), dataFinal: fimPadrao, nsrInicial: Math.trunc(Number(ultimoNsr)) + 1, modo: 'cursor' }
  }
  const retro = inteiroRhid(p.dias_retroativos, 7, 0, RHID_MAX_DIAS - 2)
  return { dataIni: somarDiasRhid(hoje, -retro), dataFinal: fimPadrao, nsrInicial: null, modo: 'retroativo' }
}

/** Requisição do AFD 671 de um equipamento (rota afd ou coletor). */
function requisicaoAfdRhid(base, token, alvo, janela, limite, timeoutMs) {
  const caminho = alvo.rota === 'coletor' ? '/report/afd_coletor_marcacao/download671' : '/report/afd/download671'
  const params = { idEquipamento: alvo.id, dataIni: janela.dataIni, dataFinal: janela.dataFinal, nsrInicial: janela.nsrInicial, limit: limite }
  return { method: 'GET', url: urlRhid(base, caminho, params), headers: cabecalhosRhid(token), texto: true, timeoutMs: timeoutMs || 120000 }
}

function lotesRhid(lista, tamanho) {
  const t = Math.max(1, Math.floor(tamanho || RHID_TAMANHO_LOTE))
  const saida = []
  for (let i = 0; i < (lista || []).length; i += t) saida.push(lista.slice(i, i + t))
  return saida
}

/**
 * Sessão autenticada: `{ base, obter(caminho, params, opcoes) → corpo, texto(req) }`, com novo login (uma vez) no 401.
 * deps: { requisitar(req, opcoes) → {status, corpo, tentativas}, baseUrl?, tentativas = 3, esperaMs = 5000, dormir?, timeoutMs }
 */
async function abrirSessaoRhid(config, deps) {
  const base = validarConfigRhid(config, deps.baseUrl)
  const opcoes = (rotulo) => ({ tentativas: deps.tentativas ?? 3, esperaMs: deps.esperaMs ?? 5000, dormir: deps.dormir, rotulo })
  const sessao = { base, token: null, logins: 0, tentativasMax: 1 }
  const logar = async () => {
    const r = await deps.requisitar(requisicaoLoginRhid(base, config.segredos, deps.timeoutMs), opcoes('RHiD login'))
    sessao.logins++
    sessao.tentativasMax = Math.max(sessao.tentativasMax, r.tentativas || 1)
    sessao.token = tokenDoLoginRhid(r.corpo)
  }
  sessao.chamar = async (montar, rotulo) => {
    if (!sessao.token) await logar()
    let renovou = false
    for (;;) {
      try {
        const r = await deps.requisitar(montar(sessao.token), opcoes(rotulo))
        sessao.tentativasMax = Math.max(sessao.tentativasMax, r.tentativas || 1)
        return r.corpo
      } catch (e) {
        if (e && e.status === 401 && !renovou) { renovou = true; await logar(); continue }
        throw e
      }
    }
  }
  // RHiD real: GET /device sem start/length responde HTTP 500, e length > 100 também (a spec diz que são opcionais).
  // Lista sempre paginada de 100 em 100 até vir menos que uma página ou atingir totalRecords.
  sessao.listar = async (caminho, rotulo) => {
    const POR_PAGINA = 100
    const todos = []
    for (let pagina = 0; pagina < 200; pagina++) {
      const corpo = await sessao.chamar((token) => ({ method: 'GET', url: urlRhid(base, caminho, { start: pagina * POR_PAGINA, length: POR_PAGINA }), headers: cabecalhosRhid(token), timeoutMs: deps.timeoutMs || 120000 }), rotulo)
      const registros = registrosRhid(corpo, rotulo)
      todos.push(...registros)
      const c = corpoJsonRhid(corpo)
      const total = Number(c && typeof c === 'object' ? c.totalRecords : NaN)
      if (registros.length < POR_PAGINA || (Number.isFinite(total) && todos.length >= total)) break
    }
    return todos
  }
  await logar()
  return sessao
}

/** Pessoas do RHiD → `ingestao_rhid_pessoas` (snapshot). Lista vazia → erro (nada é marcado como removido). */
async function importarPessoasRhid(config, sessao, deps) {
  const pessoas = sessao.pessoas || (sessao.pessoas = await sessao.listar('/person', 'pessoas'))
  if (!pessoas.length) throw new Error('RHiD devolveu nenhuma pessoa (confira se o usuário de integração pode ler Pessoas)')
  const enxutas = pessoas.map((x) => ({ id: x.id, cpf: x.cpf, pis: x.pis, name: x.name, socialName: x.socialName, registration: x.registration, status: x.status, idCompany: x.idCompany }))
  const ret = (await deps.rpc('ingestao_rhid_pessoas', { p_integracao: config.integracao_id, p_pessoas: enxutas })) || {}
  return {
    status: 'sucesso',
    lidos: pessoas.length,
    gravados: Number(ret.gravados) || 0,
    ignorados: Number(ret.ignorados) || 0,
    detalhes: { pessoas: pessoas.length, ingestao: ret, logins: sessao.logins },
    tentativas: sessao.tentativasMax,
  }
}

/**
 * Batidas: lista equipamentos, baixa o AFD 671 de cada um (do cursor em diante), lê com `deps.lerAfd` e grava em lotes
 * (`ingestao_rhid_batidas`, que atualiza o cursor do equipamento). Equipamento automático (REP-P) com erro 4xx só vira aviso.
 * deps: { rpc, lerAfd, resumoAfd?, limite?, tamanhoLote?, maxPaginas = 20 }
 */
async function importarBatidasRhid(config, entrada, sessao, deps) {
  if (typeof deps.lerAfd !== 'function') throw new Error('lerAfd indisponível (copie controlid/lib/afd.mjs no nó)')
  const p = config.parametros || {}
  const cursor = (config.cursor && config.cursor.nsr_por_equipamento) || {}
  const limite = inteiroRhid(p.limite_afd ?? deps.limite, RHID_LIMITE_AFD, 1, RHID_LIMITE_AFD)
  const maxPaginas = deps.maxPaginas ?? 20
  const explicitos = Array.isArray(p.equipamentos) && p.equipamentos.length > 0
  const dispositivos = explicitos ? [] : await sessao.listar('/device', 'equipamentos')
  let empresas = []
  if (!explicitos && p.incluir_rep_p !== false) {
    if (!sessao.pessoas) sessao.pessoas = await sessao.listar('/person', 'pessoas')
    empresas = empresasRhid(sessao.pessoas, dispositivos)
  }
  const alvos = alvosRhid(dispositivos, p, empresas)
  const tot = { lidos: 0, gravados: 0, ignorados: 0, duplicados: 0, sem_funcionario: 0 }
  const equipamentos = []
  const avisos = []
  const falhas = []
  for (const alvo of alvos) {
    const ultimo = cursor[alvo.chave]
    const janela = janelaRhid(entrada, config, ultimo)
    const resumo = { chave: alvo.chave, nome: alvo.nome, rota: alvo.rota, janela, paginas: 0, marcacoes: 0, gravados: 0, duplicados: 0, ignorados: 0, sem_funcionario: 0, ultimo_nsr: ultimo ?? null }
    try {
      let nsrInicial = janela.nsrInicial
      for (let pagina = 0; pagina < maxPaginas; pagina++) {
        const texto = textoAfdRhid(await sessao.chamar((token) => requisicaoAfdRhid(sessao.base, token, alvo, { ...janela, nsrInicial }, limite, deps.timeoutMs), `RHiD AFD ${alvo.chave}`))
        resumo.paginas++
        const leitura = deps.lerAfd(texto)
        const piso = janela.modo === 'cursor' && ultimo != null ? Number(ultimo) : -1
        const marcacoes = leitura.marcacoes.filter((m) => Number(m.nsr) > piso)
        resumo.marcacoes += marcacoes.length
        if (pagina === 0 && deps.resumoAfd) resumo.afd = deps.resumoAfd(leitura)
        for (const lote of lotesRhid(marcacoes, deps.tamanhoLote || RHID_TAMANHO_LOTE)) {
          const r = (await deps.rpc('ingestao_rhid_batidas', { p_integracao: config.integracao_id, p_equipamento: alvo.chave, p_marcacoes: lote })) || {}
          resumo.gravados += Number(r.gravados) || 0
          resumo.duplicados += Number(r.duplicados) || 0
          resumo.ignorados += Number(r.ignorados) || 0
          resumo.sem_funcionario += Number(r.sem_funcionario) || 0
          if (r.ultimo_nsr !== undefined && r.ultimo_nsr !== null) resumo.ultimo_nsr = Number(r.ultimo_nsr)
          if (Array.isArray(r.erros) && r.erros.length) resumo.erros = (resumo.erros || []).concat(r.erros).slice(0, 10)
        }
        // limite atingido → próxima página a partir do maior NSR lido
        const registros = leitura.marcacoes.length + leitura.ignoradas.length
        if (registros < limite || !leitura.marcacoes.length) break
        nsrInicial = Math.max(...leitura.marcacoes.map((m) => Number(m.nsr))) + 1
        if (pagina === maxPaginas - 1) avisos.push(`${alvo.nome}: parou após ${maxPaginas} páginas de ${limite} registros`)
      }
    } catch (e) {
      const status = e && e.status
      const msg = `${alvo.nome}: ${e && e.message ? e.message : String(e)}`.slice(0, 300)
      if (alvo.automatico && status >= 400 && status < 500 && status !== 401) avisos.push(msg)
      else falhas.push(msg)
      resumo.erro = msg
    }
    tot.lidos += resumo.marcacoes
    tot.gravados += resumo.gravados
    tot.duplicados += resumo.duplicados
    tot.ignorados += resumo.ignorados
    tot.sem_funcionario += resumo.sem_funcionario
    equipamentos.push(resumo)
  }
  if (!alvos.length) avisos.push('Nenhum equipamento REP encontrado no RHiD (confira parametros.equipamentos ou a permissão do usuário)')
  const errosBanco = equipamentos.flatMap((x) => x.erros || [])
  const falhou = falhas.length > 0
  if (falhou && !equipamentos.some((x) => !x.erro)) {
    const e = new Error(falhas.slice(0, 3).join(' | '))
    e.tentativas = sessao.tentativasMax
    throw e
  }
  return {
    status: falhou || errosBanco.length ? 'parcial' : 'sucesso',
    lidos: tot.lidos,
    gravados: tot.gravados,
    ignorados: tot.ignorados,
    erro: falhou ? falhas.slice(0, 3).join(' | ') : errosBanco.length ? `${errosBanco.length} marcação(ões) recusada(s) pelo banco` : null,
    detalhes: { equipamentos, duplicados: tot.duplicados, sem_funcionario: tot.sem_funcionario, avisos, logins: sessao.logins },
    tentativas: sessao.tentativasMax,
  }
}

/** CPF do RHiD (número, perde zeros à esquerda) → 11 dígitos, ou null. */
function cpfRhid(v) {
  const d = String(v ?? '').replace(/\D/g, '')
  if (!d || /^0+$/.test(d) || d.length > 11) return null
  return d.padStart(11, '0')
}

/**
 * Horários previstos (adendo RHiD §R.9): roda junto com as batidas, no máximo a cada `horarios_intervalo_minutos`
 * (padrão 60, pelo cursor.horarios_em), ou sempre no "Sincronizar agora"/período pedido. `importar_horarios: false` desliga.
 */
function deveImportarHorariosRhid(entrada, config, agoraMs) {
  const p = (config && config.parametros) || {}
  if (p.importar_horarios === false) return false
  if (entrada && (entrada.gatilho === 'manual' || entrada.data_inicio || entrada.data_fim)) return true
  const ultimo = Date.parse((config && config.cursor && config.cursor.horarios_em) || '')
  if (!Number.isFinite(ultimo)) return true
  const intervalo = inteiroRhid(p.horarios_intervalo_minutos, 60, 0, 24 * 60)
  return (agoraMs ?? Date.now()) - ultimo >= intervalo * 60000
}

/** Período da apuração: o pedido (≤ 90 dias, até hoje) ou [hoje − dias_horarios (padrão 40), hoje]. */
function janelaHorariosRhid(entrada, config) {
  const hoje = config && config.dia_trabalho_atual
  if (!dataValidaRhid(hoje)) throw new Error('Configuração sem dia_trabalho_atual')
  const p = (config && config.parametros) || {}
  let ini = entrada && entrada.data_inicio
  let fim = entrada && entrada.data_fim
  if (ini || fim) {
    ini = ini || fim
    fim = fim || hoje
    if (!dataValidaRhid(ini) || !dataValidaRhid(fim) || ini > fim) throw new Error(`Período inválido: ${ini} a ${fim}`)
    if (fim > hoje) fim = hoje
    if (ini > fim) ini = fim
  } else {
    fim = hoje
    ini = somarDiasRhid(hoje, -inteiroRhid(p.dias_horarios, 40, 0, RHID_MAX_DIAS - 1))
  }
  if (somarDiasRhid(ini, RHID_MAX_DIAS - 1) < fim) ini = somarDiasRhid(fim, -(RHID_MAX_DIAS - 1))
  return { dataIni: ini, dataFinal: fim }
}

/**
 * Apuração do RHiD de uma pessoa (GET /apuracao_ponto; corpo = string JSON com um objeto por dia) → dias para
 * `ingestao_rhid_horarios`: previsto = horasUteis (0 em folga/feriado), horários de strHorarioContratualSimples
 * ("08:00-13:00\r\n13:30-15:50"), feriado = nome, saldo = saldoBancoCredDeb.
 */
function diasApuracaoRhid(corpo, cpf) {
  let c = corpoJsonRhid(corpo)
  if (typeof c === 'string') c = corpoJsonRhid(c)
  if (c && !Array.isArray(c) && typeof c === 'object') {
    if (Array.isArray(c.records)) c = c.records
    else throw new Error(`RHiD apuração: ${String(c.error || c.message || 'resposta inesperada').slice(0, 200)}`)
  }
  if (!Array.isArray(c)) throw new Error('RHiD apuração: resposta sem lista de dias')
  const dias = []
  for (const d of c) {
    if (!d || typeof d !== 'object') continue
    const data = String(d.date || d.dateTimeStr || '').replace(/^(\d{4})(\d{2})(\d{2})$/, '$1-$2-$3').slice(0, 10)
    if (!dataValidaRhid(data)) continue
    const horarios = String(d.strHorarioContratualSimples || '')
      .split(/[\r\n]+/)
      .flatMap((faixa) => faixa.split('-').map((h) => h.trim()))
      .filter((h) => /^\d{1,2}:\d{2}$/.test(h))
    let feriado = null
    if (Number(d.isHoliday) > 0 || d.holiday) {
      let h = d.holiday
      if (typeof h === 'string') h = corpoJsonRhid(h)
      feriado = String((h && typeof h === 'object' && h.name) || 'Feriado').slice(0, 120)
    }
    const folga = d.folga === true
    const uteis = Math.max(0, Math.min(1440, Math.trunc(Number(d.horasUteis) || 0)))
    dias.push({
      cpf,
      data,
      previsto_minutos: folga || feriado ? 0 : uteis,
      horarios,
      folga,
      feriado,
      saldo_minutos: Number.isFinite(Number(d.saldoBancoCredDeb)) ? Math.trunc(Number(d.saldoBancoCredDeb)) : null,
    })
  }
  return dias
}

/**
 * Horários previstos: para cada CPF ligado a funcionário (ingestao_rhid_vinculados), pede a apuração do RHiD no período
 * e grava em lotes (ingestao_rhid_horarios, que reapura os dias alterados). Pessoa com erro vira aviso.
 * deps: { rpc, tamanhoLote? }
 */
async function importarHorariosRhid(config, entrada, sessao, deps) {
  const janela = janelaHorariosRhid(entrada, config)
  const vinculados = ((await deps.rpc('ingestao_rhid_vinculados', { p_integracao: config.integracao_id })) || []).map(cpfRhid).filter(Boolean)
  if (!sessao.pessoas) sessao.pessoas = await sessao.listar('/person', 'pessoas')
  const idPorCpf = new Map()
  for (const x of sessao.pessoas) { const c = cpfRhid(x && x.cpf); if (c && Number(x.id) > 0 && !idPorCpf.has(c)) idPorCpf.set(c, Number(x.id)) }
  const avisos = []
  const falhas = []
  let dias = []
  let pessoas = 0
  for (const cpf of vinculados) {
    const id = idPorCpf.get(cpf)
    if (!id) { avisos.push(`CPF …${cpf.slice(-2)} ligado, mas não está nas pessoas do RHiD`); continue }
    try {
      const corpo = await sessao.chamar((token) => ({ method: 'GET', url: urlRhid(sessao.base, '/apuracao_ponto', { idPerson: id, dataIni: janela.dataIni, dataFinal: janela.dataFinal }), headers: cabecalhosRhid(token), timeoutMs: deps.timeoutMs || 120000 }), `RHiD apuração ${id}`)
      dias = dias.concat(diasApuracaoRhid(corpo, cpf))
      pessoas++
    } catch (e) {
      falhas.push(`pessoa ${id}: ${e && e.message ? e.message : String(e)}`.slice(0, 200))
    }
  }
  if (vinculados.length && !pessoas && falhas.length) {
    const e = new Error(falhas.slice(0, 3).join(' | '))
    e.tentativas = sessao.tentativasMax
    throw e
  }
  const tot = { gravados: 0, iguais: 0, ignorados: 0, reapurados: 0 }
  for (const lote of lotesRhid(dias, deps.tamanhoLote || 2000)) {
    const r = (await deps.rpc('ingestao_rhid_horarios', { p_integracao: config.integracao_id, p_dias: lote })) || {}
    tot.gravados += Number(r.gravados) || 0
    tot.iguais += Number(r.iguais) || 0
    tot.ignorados += Number(r.ignorados) || 0
    tot.reapurados += Number(r.funcionarios_reapurados) || 0
  }
  return {
    status: falhas.length ? 'parcial' : 'sucesso',
    lidos: dias.length,
    gravados: tot.gravados,
    ignorados: tot.ignorados,
    erro: falhas.length ? `${falhas.length} pessoa(s) sem apuração: ${falhas.slice(0, 2).join(' | ')}` : null,
    detalhes: { janela, vinculados: vinculados.length, pessoas, iguais: tot.iguais, funcionarios_reapurados: tot.reapurados, avisos: avisos.slice(0, 20), logins: sessao.logins },
    tentativas: sessao.tentativasMax,
  }
}

/** Junta as saídas de `comExecucao` (pessoas, batidas) na saída do subfluxo (§12.3): pior status, somas, todos os ids. */
function juntarSaidasRhid(saidas) {
  const lista = (saidas || []).filter(Boolean)
  if (!lista.length) return { execucao_ids: [], status: 'erro', lidos: 0, gravados: 0, ignorados: 0, erro: 'Nada a fazer para este escopo' }
  const ordem = { sucesso: 0, parcial: 1, erro: 2 }
  const pior = lista.reduce((a, s) => (ordem[s.status] > ordem[a] ? s.status : a), 'sucesso')
  const erros = lista.map((s) => s.erro).filter(Boolean)
  return {
    execucao_ids: lista.flatMap((s) => s.execucao_ids || []),
    status: pior,
    lidos: lista.reduce((a, s) => a + (Number(s.lidos) || 0), 0),
    gravados: lista.reduce((a, s) => a + (Number(s.gravados) || 0), 0),
    ignorados: lista.reduce((a, s) => a + (Number(s.ignorados) || 0), 0),
    erro: erros.length ? erros.join(' | ').slice(0, 1000) : null,
  }
}

// ---------------------------------------------------------------- uso neste nó
const fontes = [() => $env, () => $vars]
const cfg = configSupabase(fontes)
const http = criarHttpN8n(this.helpers)
const execucaoN8n = $execution.id

const entrada = $input.first().json
if (!entrada.integracao_id) throw new Error('Entrada sem integracao_id')

let config = null
let sessao = null
let falhaPrevia = null
try {
  config = await chamarRpc(http, cfg, 'ingestao_integracao_config', { p_integracao: entrada.integracao_id })
  // login no RHiD (a senha e o token nunca vão para log nem para sync_execucoes)
  sessao = await abrirSessaoRhid(config, {
    baseUrl: lerVariavel('RHID_BASE_URL', fontes),
    requisitar: (req, opcoes) => requisitarComRetentativa(http, req, opcoes),
  })
} catch (e) {
  falhaPrevia = e
}

const plano = planoRhid(entrada, config)
const abertura = (tipo) => ({
  tipo,
  gatilho: entrada.gatilho,
  workflow: NOMES_WORKFLOWS.RHID_IMPORTAR,
  empresa_id: entrada.empresa_id || (config && config.empresa_id) || null,
  integracao_id: entrada.integracao_id,
  solicitacao_id: entrada.solicitacao_id || null,
  periodo_inicio: entrada.data_inicio || null,
  periodo_fim: entrada.data_fim || null,
  n8n_execution_id: execucaoN8n,
})
const rpc = (nome, args) => chamarRpc(http, cfg, nome, args)
const saidas = []
if (plano.pessoas) {
  saidas.push(await comExecucao(http, cfg, abertura('rhid_pessoas'), async () => {
    if (falhaPrevia) throw falhaPrevia
    return importarPessoasRhid(config, sessao, { rpc })
  }))
}
if (plano.batidas) {
  saidas.push(await comExecucao(http, cfg, abertura('rhid_batidas'), async () => {
    if (falhaPrevia) throw falhaPrevia
    return importarBatidasRhid(config, entrada, sessao, { rpc, lerAfd, resumoAfd })
  }))
}
// horários previstos do RHiD (folga, feriado, horário contratual) — no máximo a cada hora, sempre no manual (§R.9)
if (plano.batidas && !falhaPrevia && deveImportarHorariosRhid(entrada, config)) {
  saidas.push(await comExecucao(http, cfg, abertura('rhid_horarios'), async () => importarHorariosRhid(config, entrada, sessao, { rpc })))
}

// Saída do subfluxo (contrato §12.3)
const saida = juntarSaidasRhid(saidas)
return [{ json: { execucao_ids: saida.execucao_ids, status: saida.status, lidos: saida.lidos, gravados: saida.gravados, ignorados: saida.ignorados, erro: saida.erro } }]
